//! Noms des types d'entrees des repertoires AMD (PSP et BIOS). Source : table publique de l'outil open source coreboot `amdfwtool.h` (contrat d'interoperabilite, valeurs relues le 2026-10-12).
//! Les noms sont des identifiants de type, pas une description de contenu verifiee octet par octet.
pub fn nom(t: u32, bios: bool) -> &'static str {
    if bios { match t { 0x05 => "cle publique RTM", 0x07 => "signature BIOS", 0x60 => "APCB (configuration AGESA)", 0x61 => "APOB (sortie AGESA)", 0x62 => "image BIOS", 0x63 => "APOB NV", 0x64 => "PMU instructions", 0x65 => "PMU donnees", 0x66 => "microcode CPU", 0x68 => "APCB de secours", 0x69 => "VGA precoce", 0x6a => "configuration MP2", 0x6b => "memoire partagee PSP", 0x6d => "region NVRAM (non documente publiquement ; deduit : couvre le magasin NVAR d'AMI)", 0x70 => "pointeur repertoire niveau 2", _ => "type inconnu" } }
    else { match t {
        0x00 => "cle publique PSP", 0x01 => "amorce du PSP", 0x02 => "OS securise du PSP", 0x03 => "recuperation PSP", 0x04 => "NVRAM du PSP", 0x05 => "cle publique RTM", 0x08 => "firmware SMU", 0x09 => "debogage securise", 0x0a => "cle publique ABL", 0x0b => "chaine de fusibles PSP", 0x0c => "trustlets PSP", 0x0d => "cle des trustlets", 0x12 => "firmware SMU (2)", 0x13 => "deverrouillage de debogage",
        0x1b => "pilote d'amorcage", 0x1c => "pilote SoC", 0x1d => "pilote de debogage", 0x1f => "pilote d'interface", 0x20 => "configuration materielle IP", 0x21 => "IKEK enveloppe", 0x22 => "jeton de deverrouillage", 0x24 => "passerelle de securite", 0x25 => "firmware MP2", 0x28 => "entrees de pilotes", 0x29 => "image KVM", 0x2a => "firmware MP5", 0x2d => "pilote S0i3",
        0x30..=0x37 => "ABL (AGESA boot loader)", 0x38 => "donnees SEV", 0x39 => "code SEV", 0x3a => "liste blanche PSP", 0x3c => "amorce VBIOS", 0x40 => "pointeur repertoire niveau 2", 0x42 => "firmware DXIO", 0x44 => "firmware PHY USB", 0x45 => "politique de securite TOS", 0x47 => "TA DRTM", 0x48 | 0x4a => "recuperation A/B", 0x49 => "table BIOS",
        0x50 => "base de cles (amorce)", 0x51 => "base de cles (TOS)", 0x52 => "VERSTAGE PSP", 0x53 => "signature VERSTAGE", 0x54 => "NVRAM RPMC", 0x55 => "SPL", 0x58 => "DMCU ERAM", 0x59 => "DMCU ISR", 0x5a => "MSMU", 0x5c => "configuration SPI ROM", 0x5d => "MPIO", 0x5f => "TPM lite / SMUSCS", 0x71 => "DMCUB", 0x73 => "amorce PSP A/B", 0x76 => "RIB", _ => "type inconnu" } }
}
